INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'be-mercurius', id, '2017-01-01', 1, 'https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108877/eInvoicing+in+Belgium' FROM countries WHERE name_en = 'Belgium';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('be-mercurius', 'en', 'Mercurius platform launches for B2G Peppol invoicing', 'Belgium''s central hub for business-to-government e-invoicing goes live, built on the Peppol network from the start — the same infrastructure the 2026 B2B mandate would later extend.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'be-b2g-phasein', id, '2024-03-01', 1, 'https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108877/eInvoicing+in+Belgium' FROM countries WHERE name_en = 'Belgium';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('be-b2g-phasein', 'en', 'B2G mandate phases in by contract value, then becomes universal', 'October 2022: contracts/concessions ≥€215,000. April 2023: ≥€30,000. October 2023: below €30,000. March 2024: all public contracts and concessions, regardless of value, transposing EU Directive 2014/55/EU in full.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'be-law-2024', id, '2024-02-06', 1, 'https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108877/eInvoicing+in+Belgium' FROM countries WHERE name_en = 'Belgium';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('be-law-2024', 'en', 'Law of 6 February 2024 fixes the B2B start date', 'Parliament writes the structured e-invoicing obligation into Belgian law and sets 1 January 2026 as the mandatory start date for domestic B2B transactions. A Royal Decree issued in 2025 then sets Peppol BIS Billing 3.0 as the required technical standard.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'be-mandate', id, '2026-01-01', 0, 'https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108877/eInvoicing+in+Belgium' FROM countries WHERE name_en = 'Belgium';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('be-mandate', 'en', 'Mandatory B2B e-invoicing via Peppol', 'Structured e-invoicing became mandatory for domestic B2B transactions between Belgian VAT-registered businesses, using the Peppol BIS Billing 3.0 / EN 16931 standard.', '["Connect through a certified Peppol Access Point (or confirm your provider is one)", "Issue and receive Peppol BIS Billing 3.0 UBL invoices for all domestic B2B sales", "PDF and paper invoices no longer qualify — structured format only"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'be-penalty', id, '2026-04-01', 0, 'https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108877/eInvoicing+in+Belgium' FROM countries WHERE name_en = 'Belgium';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('be-penalty', 'en', 'Tolerance period ends — penalties enforced', 'The three-month administrative tolerance period ended; a progressive penalty regime (€1,500 / €3,000 / €5,000) now applies to non-compliant invoicing.', '["Resolve any outstanding Peppol onboarding gaps immediately — fines apply per infraction", "Audit recent invoices for structured-format compliance"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'be-ereport', id, '2028-01-01', 0, 'https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108877/eInvoicing+in+Belgium' FROM countries WHERE name_en = 'Belgium';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('be-ereport', 'en', 'Near-real-time e-reporting (5-corner Peppol model)', 'Belgium plans to introduce near-real-time digital VAT reporting through a five-corner Peppol model, reporting invoice data to the tax authority automatically.', '["Begin scoping five-corner Peppol reporting capability with your Access Point provider", "Confirm this remains on schedule closer to the date — final implementing rules are still pending"]');
